// Compile-verified against minecraft-common.jar + minecraft-client-only.jar (26.2) with JDK 25 javac.
// Every symbol below appeared in javap/javac output in this run.
import net.minecraft.client.Minecraft;
import net.minecraft.client.multiplayer.ClientLevel;
import net.minecraft.client.player.LocalPlayer;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.network.chat.Component;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.attribute.EnvironmentAttributes;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.RespawnAnchorBlock;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.HitResult;

public final class AnchorProbe {
    public static void tick() {
        Minecraft mc = Minecraft.getInstance();
        LocalPlayer me = mc.player;
        ClientLevel level = mc.level;
        if (me == null || level == null) return;

        if (!(mc.hitResult instanceof BlockHitResult hit) || hit.getType() != HitResult.Type.BLOCK) return;

        BlockPos anchorPos = hit.getBlockPos();
        BlockState state = level.getBlockState(anchorPos);
        if (!state.is(Blocks.RESPAWN_ANCHOR)) return;   // TypedInstance.is(Block)

        // Client-readable stand-in for the ServerLevel-only RespawnAnchorBlock.canSetSpawn(...).
        boolean anchorWorksHere =
            level.environmentAttributes().getValue(EnvironmentAttributes.RESPAWN_ANCHOR_WORKS, anchorPos);

        int charge = state.getValue(RespawnAnchorBlock.CHARGE);   // StateHolder.getValue -> Integer

        ItemStack held = me.getItemInHand(InteractionHand.MAIN_HAND);
        boolean holdingGlowstone = !held.isEmpty() && held.is(Items.GLOWSTONE);   // TypedInstance.is(Item)

        BlockPos placeAt = anchorPos.relative(hit.getDirection());   // NOT offset(Direction)
        boolean free = level.isEmptyBlock(placeAt) && level.getFluidState(placeAt).isEmpty();
        Direction back = hit.getDirection().getOpposite();

        if (holdingGlowstone && free && charge < RespawnAnchorBlock.MAX_CHARGES) {
            me.swing(InteractionHand.MAIN_HAND);   // swing(InteractionHand, boolean) also exists
        }

        // Local chat on 26.2: Minecraft -> gui -> hud -> getChat() -> addClientSystemMessage.
        // Not gui.getChat() (gone), not chat.addMessage(Component) (gone).
        mc.gui.hud.getChat().addClientSystemMessage(Component.literal(
            "anchor charge=" + charge + " works=" + anchorWorksHere
                + " place=" + placeAt.above().immutable() + " back=" + back
                + " scaled=" + RespawnAnchorBlock.getScaledChargeLevel(state, 15)));
    }
}
